import { expect, test, uniqueName } from "../../fixtures";

test.describe("Manage vendors", () => {
  test("a vendor under review cannot be edited", { tag: "@VEN-09" }, async ({ apiAs }) => {
    // Arrange: a member creates a vendor and submits it, moving it to "in_review".
    const member = await apiAs("member");
    const created = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Acme Freight"),
        category: "logistics",
        contact_email: "ops@acmefreight.example",
      },
    });
    expect(created.status()).toBe(201);
    const vendor = await created.json();

    const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
    expect(submitted.status()).toBe(200);
    expect((await submitted.json()).status).toBe("in_review");

    // Act: attempt to change the contact email while under review.
    const response = await member.patch(`/api/vendors/${vendor.id}`, {
      data: { contact_email: "billing@acmefreight.example" },
    });

    // Assert
    expect(response.status()).toBe(409);
    expect((await response.json()).error.code).toBe("vendor_locked");
  });
});
